#!/usr/bin/env bash
# inject-product.sh -- hook the Endospore product fragment into the GrapheneOS `lynx` product (E.2).
#
# The lynx product makefile (vendor/google_devices/lynx/lynx.mk) is "Generated by adevtool; do not edit",
# so we don't commit an edit into it -- instead this script appends, ONCE (idempotent), an inherit of our
# assembled vendor/endospore/endospore.mk. Run it AFTER `adevtool generate-all -d lynx` (which (re)writes
# lynx.mk) and AFTER stage-vendor.sh (which assembles vendor/endospore), and BEFORE `m`. Re-running after a
# regenerate simply re-applies the line. Keeping the product name `lynx` means generate-release.sh lynx
# <build> and the rest of the E.1 release/signing tooling keep working unchanged.
#
# This is the GrapheneOS analogue of the FP3's recorded device-tree edits (the AVB BoardConfig lines): a
# small, scripted, idempotent injection re-applied at build time rather than a committed change to an
# out-of-repo / generated tree.
#
# What counts as already wired (NWP-20261027-18): only a LIVE directive -- a line that is not a comment
# (no leading `#` after optional whitespace). Block 1 and 2 need a live line naming the path; block 3 needs
# a live `BUILD_BROKEN_ELF_PREBUILT_PRODUCT_COPY_FILES := true`. A commented-out inherit would otherwise skip
# block 1 and, through inherit-product-if-exists, build an image WITHOUT the Endospore fragment, silently; a
# `:= false` would skip block 3 and fail the bundled-app JNI libs. A block this script appended itself is
# live, so a wired tree re-runs as a no-op.
#
# Usage: inject-product.sh <graphene-tree-root> [device=lynx]
set -euo pipefail
TREE="${1:?usage: inject-product.sh <graphene-tree-root> [device]}"
DEV="${2:-lynx}"
MK="$TREE/vendor/google_devices/$DEV/$DEV.mk"
BC="$TREE/vendor/google_devices/$DEV/BoardConfig.mk"
LINE='$(call inherit-product-if-exists, vendor/endospore/endospore.mk)'
MARK='# --- endospore: inherit edition product fragment (inject-product.sh) ---'
# Wire our sepolicy into the board. The workers run /system binaries, so the domain belongs in the
# system-side private policy: SYSTEM_EXT_PRIVATE_SEPOLICY_DIRS (BOARD_PLAT_PRIVATE_SEPOLICY_DIR is
# obsolete in this tree). Same var the FP3 used (editions/diaspore/build/p4.2c-sepolicy-wire.sh).
SEPOL_LINE='SYSTEM_EXT_PRIVATE_SEPOLICY_DIRS += vendor/endospore/sepolicy'
SEPOL_MARK='# --- endospore: confined SELinux domain (system-side private policy) ---'

[ -f "$MK" ] || { echo "ERROR: $MK not found -- run adevtool generate-all -d $DEV first" >&2; exit 1; }
[ -f "$BC" ] || { echo "ERROR: $BC not found -- run adevtool generate-all -d $DEV first" >&2; exit 1; }

# 1. Product fragment inherit (keeps the product name $DEV so the E.1 release tooling is unchanged).
if grep -qE '^[[:space:]]*[^#[:space:]].*vendor/endospore/endospore\.mk' "$MK"; then
  echo "[inject-product] product inherit already present in $MK"
else
  printf '\n%s\n%s\n' "$MARK" "$LINE" >> "$MK"
  echo "[inject-product] appended endospore inherit to $MK"
fi

# 2. Board sepolicy dir (so the nowhere / nowhere_chooser domains + login socket types are compiled in).
if grep -qE '^[[:space:]]*[^#[:space:]].*vendor/endospore/sepolicy' "$BC"; then
  echo "[inject-product] sepolicy dir already wired in $BC"
else
  printf '\n%s\n%s\n' "$SEPOL_MARK" "$SEPOL_LINE" >> "$BC"
  echo "[inject-product] wired SYSTEM_EXT_PRIVATE_SEPOLICY_DIRS into $BC"
fi

# 3. Allow legacy ELF .so in PRODUCT_COPY_FILES. Newer AOSP soong (BOARD_API_LEVEL >= 202604) rejects ELF
# prebuilts copied via PRODUCT_COPY_FILES; our bundled-app JNI libs (OrganicMaps's,
# generated into vendor/endospore/prebuilts/default-apps-jni.mk) are valid prebuilts declared the legacy way
# -- exactly as on the FP3, whose older LineageOS base doesn't enforce the check. The flag is honoured by
# this tree's build/make (core/Makefile + core/board_config.mk).
BROKEN_LINE='BUILD_BROKEN_ELF_PREBUILT_PRODUCT_COPY_FILES := true'
BROKEN_MARK='# --- endospore: allow legacy ELF .so (bundled-app JNI) in PRODUCT_COPY_FILES ---'
if grep -qE '^[[:space:]]*BUILD_BROKEN_ELF_PREBUILT_PRODUCT_COPY_FILES[[:space:]]*:?=[[:space:]]*true[[:space:]]*$' "$BC"; then
  echo "[inject-product] BUILD_BROKEN ELF flag already present in $BC"
else
  # make's last assignment wins, so this overrides an earlier generated `:= false` (left as it is).
  printf '\n%s\n%s\n' "$BROKEN_MARK" "$BROKEN_LINE" >> "$BC"
  echo "[inject-product] wired BUILD_BROKEN_ELF_PREBUILT_PRODUCT_COPY_FILES into $BC"
fi
